"""Repository-configured technical interface visual builders."""
def render_assets(cfg, frame, stars, text, orbit, core):
    def hero():
        layers=''.join(f'<text x="600" y="{250+i*7}" fill="#0a3654" fill-opacity="{.42-i*.07:.2f}" font-family="Inter,system-ui,sans-serif" font-size="62" font-weight="700" text-anchor="middle" letter-spacing="7">KRISHNA SAI</text>' for i in range(5))
        return frame('NEXUS — Krishna Sai Channalli',1200,520,stars(1200,520,34)+text(70,58,'N E X U S',14,'#7cefff',sp=7)+text(1128,58,'PROFILE INTERFACE // 01',10,'#91b5c3','end',1)+orbit(600,252,328,82,23,'20 11')+orbit(600,252,250,120,37,'5 14')+layers+'<text x="600" y="278" fill="#effdff" font-family="Inter,system-ui,sans-serif" font-size="62" font-weight="700" text-anchor="middle" letter-spacing="7">KRISHNA SAI</text><text x="600" y="344" fill="#effdff" font-family="Inter,system-ui,sans-serif" font-size="62" font-weight="700" text-anchor="middle" letter-spacing="7">CHANNALLI</text><text x="600" y="390" fill="#78ecff" font-family="monospace" font-size="14" text-anchor="middle" letter-spacing="3">AI SYSTEMS · AGENTS · AUTOMATION · ENGINEERING</text><path d="M180 430H1020" stroke="#67eaff" stroke-opacity=".42" stroke-dasharray="18 16"><animate attributeName="stroke-dashoffset" values="0;-102" dur="8.1s" repeatCount="indefinite"/></path>')
    def matrix():
        rows=[]; y=112
        for index,(domain,items) in enumerate(cfg['technologies'].items()):
            accent=['#66eaff','#a78bfa','#6cb8ff','#72e8c1','#79d9b5','#f2bb68','#76d8ff','#bfc9d3'][index]
            rows.append(f'<path d="M80 {y+20}H1120" stroke="{accent}" stroke-opacity=".26"/><circle cx="100" cy="{y}" r="5" fill="{accent}"><animate attributeName="opacity" values=".35;1;.35" dur="{2.2+index*.55}s" repeatCount="indefinite"/></circle>{text(122,y+5,domain.upper(),13,accent,sp=2)}{text(340,y+5," · ".join(items),11,"#d8edf4")}<path d="M1030 {y}H1100" stroke="{accent}" stroke-width="2" stroke-dasharray="10 15"><animate attributeName="stroke-dashoffset" values="0;-50" dur="{5+index}s" repeatCount="indefinite"/></path>')
            y+=70
        return frame('Technology matrix',1200,710,stars(1200,710,30)+text(70,55,'01 // TECHNOLOGY MATRIX',16,'#7cefff',sp=3)+text(70,82,'VERIFIED PUBLIC-REPOSITORY INVENTORY',10,'#90b3c0',sp=2)+''.join(rows)+text(80,670,'ANIMATED SIGNALS REPRESENT TECHNOLOGY GROUPS, NOT PROFICIENCY METRICS.',10,'#8ba9b6'))
    def network():
        nodes=[('AI',600,105,30),('PYTHON',350,230,25),('TYPESCRIPT',600,230,25),('RUST',850,230,22),('FASTAPI',350,385,22),('REACT',600,385,22),('AXUM',850,385,20),('POSTGRESQL',350,535,24),('NEXT.JS',600,535,22),('DOCKER',850,535,22),('SYSTEMS',600,660,35)]
        edges=[(600,105,350,230),(600,105,600,230),(600,105,850,230),(350,230,350,385),(600,230,600,385),(850,230,850,385),(350,385,350,535),(600,385,600,535),(850,385,850,535),(350,535,600,660),(600,535,600,660),(850,535,600,660)]
        lines=''.join(f'<path d="M{x1} {y1}Q{(x1+x2)//2} {(y1+y2)//2-35} {x2} {y2}" fill="none" stroke="#5deaff" stroke-opacity=".38" stroke-dasharray="5 11"><animate attributeName="stroke-dashoffset" values="0;-64" dur="{4+i*.7}s" repeatCount="indefinite"/></path>' for i,(x1,y1,x2,y2) in enumerate(edges))
        points=''.join(f'<g><circle cx="{x}" cy="{y}" r="{r}" fill="#071827" stroke="#78eaff"/><circle cx="{x}" cy="{y}" r="{r*.25}" fill="#b6fbff" filter="url(#bloom)"><animate attributeName="opacity" values=".4;1;.4" dur="{2.4+i*.5}s" repeatCount="indefinite"/></circle>{text(x,y+4,n,10,"#e9feff","middle")}</g>' for i,(n,x,y,r) in enumerate(nodes))
        return frame('Technology relationship network',1200,740,stars(1200,740,26)+text(70,54,'02 // TECHNOLOGY NETWORK',16,'#7cefff',sp=3)+text(70,82,'CONCEPTUAL ENGINEERING ECOSYSTEM — NOT A DEPENDENCY GRAPH',10,'#90b3c0',sp=1)+lines+points)
    def projects():
        rows=[]; y=165
        for i,p in enumerate(cfg['projects']):
            stack=p['evidence'].split('.')[0]
            rows.append(f'<a href="{p["repository"]}"><g><path d="M78 {y+25}H1122" stroke="#63eaff" stroke-opacity=".24"/><text x="100" y="{y}" fill="#7cefff" font-family="monospace" font-size="11">0{i+1}</text>{text(160,y,p["name"],16,"#f0feff")}{text(460,y,p["description"],11,"#bed8e2")}{text(460,y+22,stack,10,"#86aaba")}<circle cx="1080" cy="{y-6}" r="6" fill="#74edc0"><animate attributeName="opacity" values=".45;1;.45" dur="{3+i*.8}s" repeatCount="indefinite"/></circle></g></a>')
            y+=105
        return frame('Project systems',1200,620,stars(1200,620,20)+text(70,55,'03 // PROJECT SYSTEMS',16,'#7cefff',sp=3)+text(100,112,'SYSTEM',11,'#91b5c3',sp=2)+text(460,112,'VERIFIED PURPOSE / CORE STACK',11,'#91b5c3',sp=2)+text(1040,112,'PUBLIC',11,'#91b5c3',sp=2)+''.join(rows))
    def opero():
        stages=[('INPUT',600,120),('INTELLIGENCE',600,220),('LOCAL TOOLS',320,340),('AUTOMATION',600,340),('RESEARCH',880,340),('EXECUTION',600,460),('VERIFY',600,560),('RESULT',600,660)]
        paths=[]
        for i in range(len(stages)-1):
            a,b=stages[i],stages[i+1]
            if i==1:
                for target in stages[2:5]: paths.append((a[1],a[2],target[1],target[2]))
            elif i in (2,3,4): paths.append((a[1],a[2],600,460))
            elif i not in (1,): paths.append((a[1],a[2],b[1],b[2]))
        flow=''.join(f'<path d="M{x1} {y1+25}L{x2} {y2-25}" stroke="#66eaff" stroke-width="2" stroke-dasharray="8 12"><animate attributeName="stroke-dashoffset" values="0;-60" dur="{3.1+i*.6}s" repeatCount="indefinite"/></path>' for i,(x1,y1,x2,y2) in enumerate(paths))
        boxes=''.join(f'<g><rect x="{x-100}" y="{y-25}" width="200" height="50" rx="8" fill="#071827" stroke="#75eaff"/><text x="{x}" y="{y+5}" fill="#eaffff" font-family="monospace" font-size="12" text-anchor="middle">{n}</text></g>' for n,x,y in stages)
        return frame('The-Opero autonomous operator architecture',1200,740,stars(1200,740,24)+text(70,54,'04 // THE-OPERO — AUTONOMOUS OPERATOR CORE',16,'#7cefff',sp=2)+text(70,82,'OPEN PERSONAL EXECUTION & RESPONSE OPERATOR · PYTHON · PYQT6 · GEMINI · LOCAL EXECUTION',10,'#9ab8c5')+flow+boxes)
    def system_map(title,subtitle,items,color):
        x=600; positions=[(250,260),(600,180),(950,260),(250,475),(600,555),(950,475)]; use=items[:6]; paths=''.join(f'<path d="M600 370Q{(600+px)//2} {(370+py)//2-38} {px} {py}" fill="none" stroke="{color}" stroke-opacity=".5" stroke-dasharray="5 10"><animate attributeName="stroke-dashoffset" values="0;-52" dur="{4+i*.8}s" repeatCount="indefinite"/></path>' for i,(_,px,py) in enumerate([(n,*positions[i]) for i,n in enumerate(use)])); nodes=''.join(f'<g><circle cx="{px}" cy="{py}" r="35" fill="#071827" stroke="{color}"/><text x="{px}" y="{py+4}" fill="#effdff" font-family="monospace" font-size="10" text-anchor="middle">{n}</text></g>' for i,n in enumerate(use) for px,py in [positions[i]])
        return frame(title,1200,670,stars(1200,670,25)+text(70,54,title.upper(),16,color,sp=3)+text(70,82,subtitle,10,'#9ab8c5')+paths+core(x,370,58)+text(x,375,title.split()[0].upper(),13,'#06131d','middle',2)+nodes)
    def automation():
        stages=['TRIGGER','DETECT','UNDERSTAND','DECIDE','EXECUTE','VERIFY','REPORT']; y=290; x0=110; each=165; circles=''.join(f'<g><circle cx="{x0+i*each}" cy="{y}" r="35" fill="#071827" stroke="#75eaff"/><text x="{x0+i*each}" y="{y+4}" fill="#effdff" font-family="monospace" font-size="10" text-anchor="middle">{name}</text></g>' for i,name in enumerate(stages)); line='<path d="M110 290H1100" stroke="#67eaff" stroke-width="3" stroke-dasharray="16 14"><animate attributeName="stroke-dashoffset" values="0;-120" dur="8.1s" repeatCount="indefinite"/></path>'
        return frame('Automation engine',1200,480,stars(1200,480,20)+text(70,54,'05 // AUTOMATION ENGINE',16,'#7cefff',sp=3)+text(70,82,'REPOSITORY-VERIFIED PATTERNS: BROWSER CONTROL · VOICE INTERPRETATION · REPOSITORY ANALYSIS · FINANCIAL INTELLIGENCE',10,'#9ab8c5')+line+circles+text(600,390,'SIGNAL FLOW IS A VISUAL MODEL OF THE REPOSITORY-SUPPORTED ENGINEERING WORK.',10,'#9ab8c5','middle'))
    def terminal():
        lines=[('$ nexus status','SYSTEM       PROFILE INTERFACE'),('$ profile','KRISHNA SAI CHANNALLI'),('$ focus','AI SYSTEMS / AGENTS / AUTOMATION'),('$ current','THE-OPERO'),('$ scan projects','[✓] THE-OPERO   [✓] VAULTIQ AI   [✓] LIFEOS AI   [✓] PRISM')]; out=''.join(text(130,145+i*65,a,13,'#7cefff')+text(130,169+i*65,b,12,'#e6f7ff') for i,(a,b) in enumerate(lines))
        return frame('NEXUS terminal',1200,510,stars(1200,510,16)+text(70,54,'06 // NEXUS TERMINAL',16,'#7cefff',sp=3)+'<path d="M90 88L1110 58V445L90 475Z" fill="#030b14" fill-opacity=".92" stroke="#62eaff" stroke-width="2"/>'+out+'<rect x="130" y="450" width="9" height="16" fill="#8ef8ff"><animate attributeName="opacity" values="1;0;1" dur="1s" repeatCount="indefinite"/></rect>')
    return {'hero.svg':hero(),'technology-matrix.svg':matrix(),'technology-network.svg':network(),'project-systems.svg':projects(),'opero-architecture.svg':opero(),'vaultiq-system.svg':system_map('VaultIQ AI','FINANCIAL INTELLIGENCE: BUDGET · INVESTING · FRAUD PROTECTION · GOALS · SCENARIO PLANNING',['EXPENSES','GOALS','PORTFOLIO','BUDGET','INVEST','FRAUD'],'#76d8ff'),'lifeos-system.svg':system_map('LifeOS AI','AI LIFE-MANAGEMENT: CAREER · LIFE · PLANNER · SKILL · STUDY · STARTUP · FUTURE',['CAREER','LIFE','PLANNER','SKILL','STUDY','STARTUP'],'#72e8c1'),'prism-system.svg':system_map('PRISM','CODE INTELLIGENCE: TREE-SITTER · LOCAL INDEXING · RANKED SEARCH · CHANGE IMPACT',['REPOSITORY','TREE-SITTER','INDEX','SEARCH','MAP','IMPACT'],'#a78bfa'),'automation-engine.svg':automation(),'terminal.svg':terminal()}
